# Each item: (env, label, title, lean_names, uses, notready, text)
# env in {definition, theorem, lemma, proposition, corollary, remark}
# lean_names: list of declaration names (without AnalyticTheory. prefix)
# uses: list of labels; notready: True if placeholder
ITEMS = []
def add(env, label, title, lean, uses, notready, text):
    ITEMS.append(dict(env=env, label=label, title=title, lean=lean, uses=uses, notready=notready, text=text))

# ---------------- Chapter 1: Introduction / terminology
add('definition','def:local-field','Local field',['IsLocalField'],[],False,
 r'A local field is a field $K$ with a non-trivial non-archimedean absolute value for which $K$ is complete.')
add('definition','def:function-field','Function field',['IsFunctionFieldOver'],[],False,
 r'$F\,|\,K$ is a function field: finitely generated of transcendence degree $1$ over $K$, with $K$ algebraically closed in $F$.')
add('definition','def:genus','Genus (placeholder)',['genus'],['def:function-field'],True,
 r'The genus of a function field, defined via Riemann--Roch. Placeholder: not in Mathlib.')
add('definition','def:conservative','Conservative',['IsConservative'],['def:genus'],False,
 r'$F\,|\,K$ is conservative if its genus does not change under finite algebraic constant field extensions.')
add('definition','def:elliptic','Elliptic function field',['IsEllipticOver'],['def:conservative','def:function-field'],False,
 r'An elliptic function field is a conservative function field of genus $1$.')
add('definition','def:degree-one-prime','Prime divisor of degree one (placeholder)',['HasPrimeOfDegreeOne'],[],True,
 r'$F\,|\,K$ has a prime divisor of degree $1$. Placeholder predicate.')
add('definition','def:constant-extension','Constant field extension',['IsConstantExtension'],[],False,
 r'$FL$ is the constant field extension of $F$ by $L$: generated by the images of $F$ and $L$.')
add('definition','def:splitting-field','Splitting field',['IsSplittingField'],['def:degree-one-prime','def:constant-extension'],False,
 r'$L$ is a splitting field of $F\,|\,K$ if $FL\,|\,L$ has a prime divisor of degree $1$.')

# ---------------- Chapter 2: Fields of periodic functions (§2)
