# ---------------- Chapter 5: §5
add('theorem','thm:XII','Theorem XII',['thmXII_elliptic'],['def:FKQ'],True,
 r'$F_K(\mathbf Q)$ is elliptic over $K$, with constant extension $F_L(q)$ over $L$.')
add('theorem','thm:XIII','Theorem XIII',['thmXIII_prime_degrees'],['thm:XII'],True,
 r'Prime divisors of $F_K(\mathbf Q)$ correspond to $L$-conjugacy classes mod$^\times Q\sigma$, with residue field $L(\alpha)$.')
add('theorem','thm:XIV','Theorem XIV',['thmXIV_divisors'],['thm:XIII'],True,
 r'The divisor group of $F_K(\mathbf Q)$ is $D_K(\mathbf Q)$; each divisor is an $N_{\mathbf Q}$-norm.')
add('corollary','cor:XIIIa','Corollary XIIIa (index)',['corXIIIa_index'],['thm:XIII'],True,
 r'$F_K(\mathbf Q)$ has index $n$.')
add('corollary','cor:XIIIb','Corollary XIIIb (minimal splitting field)',['corXIIIb_minimal'],['thm:XIII'],True,
 r'$L$ is the minimal algebraic splitting field of $F_K(\mathbf Q)$.')
add('theorem','thm:XV','Theorem XV (Abel--Jacobi for semi-periodic functions)',['thmXV_abel_jacobi'],['thm:XIV','prop:abel-jacobi-1'],False,
 r'$C^0_K(\mathbf Q)\cong N L^\times/q$.')
add('corollary','cor:XVa','Corollary XVa',['corXVa_quotient'],['thm:XV'],False,
 r'$C^0_K(\mathbf Q)\subset C^0_K(q)$ with quotient $K^\times/NL^\times$.')
add('lemma','lem:s5-h90','Hilbert 90 for cyclic and finite-order automorphisms',['exists_h90','exists_h90_of_finOrder'],[],False,
 r'If $\sigma$ generates $\mathrm{Gal}(L|K)$ and $N(x)=1$ then $x=y/\sigma y$; also for any automorphism of finite order of a field, with $N=\prod_{i<\mathrm{ord}}\sigma^i$. Proved for all universes.')
add('lemma','lem:s5-formula65','Formula (65)',['degQ_PhiQ_divAct'],['thm:XIV'],False,
 r'$\deg_q(sw)=\deg_q w$ and $\Phi_q(sw)=\sigma\Phi_q(w)\cdot Q^{\deg w}$ for $s=\tau_Q\sigma$.')
add('lemma','lem:s5-norm-const','Every constant is a norm of a periodic function',['exists_norm_const'],['lem:s5-formula65'],False,
 r'Every $a\in K^\times$ is $\prod_{i<n}(\tau_Q\sigma)^i g$ for some $q$-periodic $g$ (quotient of theta functions).')
add('theorem','thm:XVI','Theorem XVI (norm theorem)',['thmXVI_norm'],['thm:XIV','thm:XV'],False,
 r'Every semi-periodic $f\neq 0$ is the norm of some $g\in F_L(q)$.')
add('theorem','tab:cohomology','Table of cohomology groups',['table_cohomology'],['thm:XVI'],False,
 r'$H^0$ and $H^1$ of $D_L(q)$, $D^0_L(q)$, $C^0_L(q)$, $P_L(q)$, $F_L(q)^\times$. Proved in \texttt{Sec5Table}, \texttt{Sec5Row4}, \texttt{Sec5Row5}, \texttt{Sec5Final}.')
add('lemma','lem:s5-split-cyclic','Algebras split by a cyclic extension with surjective norm',['split_of_cyclic','matrix_descent','exists_inner_of_semilinear','span_fixed_eq_top'],['lem:s5-h90'],False,
 r'If $\sigma$ has finite order on $F$, fixed field $E$, and every $e\in E^\times$ is $\prod\sigma^i g$, then $F\otimes_E A\cong M_m(F)$ implies $A\cong M_m(E)$ (Galois descent, Skolem--Noether, Speiser).')
add('lemma','lem:s5-split-base','Base change of split algebras',['split_of_extension','split_tensor_tower'],[],False,
 r'$E\otimes_k A\cong M_m(E)$ implies $F\otimes_k A\cong M_m(F)$ for $F\supseteq E$; and $F\otimes_k A\cong M_m(F)$ implies $F\otimes_E(E\otimes_k A)\cong M_m(F)$.')
add('lemma','lem:s5-specialization','Specialization of split algebras',['split_of_specialization','injective_of_split','exists_stable_lattice','exists_evalAtOne'],['lem:s5-split-base'],False,
 r'If $F\otimes_L B\cong M_m(F)$ and $F$ has a discrete valuation ring $O\supseteq L$ with an $L$-algebra map $O\to L$ (evaluation at a rational point of $F_L(q)$), then $B\cong M_m(L)$.')
add('corollary','cor:XVIa','Corollary XVIa (Brauer)',['corXVIa_brauer'],['thm:XVI'],False,
 r'$\mathrm{Br}(F_K(\mathbf Q))\to\mathrm{Br}(F_L(q))$ is injective.')
add('corollary','cor:XVIb','Corollary XVIb',['corXVIb_splitting'],['cor:XVIa'],False,
 r'An algebra is split by $F_K(\mathbf Q)$ iff it is split by $L$.')

