def _upd(label, **kw):
    for it in ITEMS:
        if it['label'] == label:
            it.update(kw); return
    raise KeyError(label)

def _addlean(label, *names):
    for it in ITEMS:
        if it['label'] == label:
            it['lean'] = list(it['lean']) + [n for n in names if n not in it['lean']]; return
    raise KeyError(label)

def _adduses(label, *labs):
    for it in ITEMS:
        if it['label'] == label:
            it['uses'] = list(it['uses']) + [l for l in labs if l not in it['uses']]; return
    raise KeyError(label)

